static __be16 vlan_get_protocol_dgram(struct sk_buff *skb)
{
	__be16 proto = skb->protocol;

	if (unlikely(eth_type_vlan(proto) && skb_mac_header_was_set(skb))) {
		int mac_offset = skb_mac_offset(skb);
		u8 *skb_orig_data = skb->data;
		int skb_orig_len = skb->len;

		if (mac_offset >= 0)
			return proto;

		skb_push(skb, -mac_offset);
		proto = __vlan_get_protocol(skb, proto, NULL);
		skb->data = skb_orig_data;
		skb->len = skb_orig_len;
	}

	return proto;
}

static __be16 vlan_get_protocol_dgram(const struct sk_buff *skb)
{
	__be16 proto = skb->protocol;

	if (unlikely(eth_type_vlan(proto))) {
		int mac_offset = skb_mac_offset(skb);
		unsigned int vlan_depth = skb->mac_len;
		unsigned int parse_depth = VLAN_MAX_DEPTH;

		/* Only adjust for SOCK_DGRAM where data points past MAC header */
		if (!skb_mac_header_was_set(skb) || mac_offset >= 0)
			return proto;

		if (vlan_depth) {
			if (vlan_depth < VLAN_HLEN)
				return 0;
			vlan_depth -= VLAN_HLEN;
		} else {
			vlan_depth = ETH_HLEN;
		}

		/* Adjust vlan_depth by mac_offset to account for data pointer position */
		do {
			struct vlan_hdr vhdr, *vh;

			vh = skb_header_pointer(skb, mac_offset + vlan_depth,
						sizeof(vhdr), &vhdr);
			if (unlikely(!vh || !--parse_depth))
				return proto;

			proto = vh->h_vlan_encapsulated_proto;
			vlan_depth += VLAN_HLEN;
		} while (eth_type_vlan(proto));
	}

	return proto;
}
